    [1969] = {
        category = "Achievements",
        source = "Raiding with Leashes IV: Wrath of the Lick King -> Algalon pet battle",
        itemId = 142100,
        sourceAchievementId = 11320,
        description = "Collect the Wrath raid-pet set, then win Algalon's special pet battle; the achievement alone does not teach Stardust.",
        difficulty = "hard",
        difficultyReason = "Sixteen raid pets plus a difficult three-legendary pet battle.",
        commentIDs = { 2435300, 2441192, 2444132 },
        waypoints = {
            { mapID = 120, x = 0.41509999999999997, y = 0.2437, step = 2, label = "Algalon - OUTDOOR pet battle" },
            { mapID = 118, x = 0.7509999999999999, y = 0.218, step = 1, label = "Trial of the Crusader - collection source" },
            { mapID = 120, x = 0.415, y = 0.177, step = 1, label = "Ulduar - collection source" },
            { mapID = 118, x = 0.539, y = 0.8740000000000001, step = 1, label = "Icecrown Citadel - collection source" },
        },
        npcId = 115158,
        petNPCID = 115158,
        name = "Stardust",
        reviewedAt = "2026-11-16",
        legionPetGuide = true,
        sourceType = "Achievements",
        stepCount = 7,
        acquisition = "Difficulty: Hard - Sixteen raid pets plus a difficult three-legendary pet battle.\n\n1. Collect and learn the 16 pets listed in Raiding with Leashes IV from Trial of the Crusader, Ulduar and Icecrown Citadel. Learning caged pets counts. Snobold Runt is an extra rare pet and is NOT required for this achievement.\n\n2. Check your mail for Celestial Invitation after the achievement. Use it to accept A Celestial Invitation, then visit Algalon at the base of Ulduar's outdoor stairs, 41.51,24.37 in the Storm Peaks. This is not the raid boss room.\n\n3. Bring three level-25 pets and inspect Algalon's team before starting. One documented approach uses Macabre Marionette with Siphon Life / Dead Man's Party / Maraca, Fiendish Imp with Rush / Immolation, and Magical Crawdad with Wish / Renewing Mists / Snap. Equivalent strong strategies also work; this is not a character-level fight.\n\n4. Against Comet, use the Marionette's Siphon Life, Dead Man's Party, then Maraca twice. The Marionette and Comet should die together; if an early critical hit prevents the second Maraca, heal and restart rather than sacrificing the rest of the strategy.\n\n5. Against Cosmos, bring in Fiendish Imp and use Rush, then Immolation. Cosmos forces the Crawdad in: use Wish, Renewing Mists, then Snap, and manually swap back to the Imp. Repeat Rush / Immolation, forced Crawdad swap, Wish / Renewing Mists / Snap, then Imp until Cosmos dies. The Imp heals on the bench while Wish supports the Crawdad.\n\n6. When Constellatius enters, keep the Imp alive on the bench and leave the Crawdad active. Use Wish, Renewing Mists and Snap / passes to survive the 15-round Apocalypse countdown. Apocalypse kills the active Crawdad and Constellatius; the healthy benched Imp survives to win. Keep the bench reserve alive rather than using every pet as disposable damage.\n\n7. Win the full battle, turn in Algalon's quest and use the rewarded Stardust pet. Heal outside battle and retry if necessary; no additional raid drop is required once the invitation is unlocked.",
        tips = "",
        wowheadUrl = "https://www.wowhead.com/npc=115158",
        references = {
            "https://www.wowhead.com/npc=115158",
            "https://www.wowhead.com/item=142100",
